Ext.define('BNK.view.HumanResource.hwm.HwmDayAply53MViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.HwmDayAply53MViewController',

    config: {
        viewId: 'HwmDayAply52M'
    },

    /* GPS 수신 */
    getGPS: function(btnName) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            params = {
                scope : me
            };

        // 이미 위치조회 실행 중일 경우, 중복 실행 차단
        if(vm.get('data.isSearching')){
            return;
        }

        vm.set('gps', null);
        vm.set('data.isSearching', true);

        var successcb = function(pos) {
            try{

                var gps = pos.coords;

                var latitude = gps.latitude,	// 위도
                    longitude = gps.longitude;	// 경도

                var eachDist = ''; // 문구

                if(gps && latitude && longitude) {

                    vm.set('gps', gps);

                    // 근무지와 현재위치의 거리 계산
                    var workZoneGps = vm.get('workZoneGps');
                    for(var i in workZoneGps){
                        var location = workZoneGps[i].wkplcNm;
                        eachDist += me.measureDistance(gps, Number(workZoneGps[i].gpsLatdVal), Number(workZoneGps[i].gpsLotdVal), location);
                        eachDist += '<br>';
                    }

                    clearInterval(vm.get('timerId'));
                    vm.set('timerId', null);
                    vm.set('data.isSearching', false);
                    refs.nowLocation.setHtml(eachDist);

                    // 지도에 마크
                    Native.addMapMarker('googleMapPanel', '현재위치', gps.latitude, gps.longitude);
                }
                else {
                    eachDist = 'GPS 위도/경도 조회 실패.';

                    clearInterval(vm.get('timerId'));
                    vm.set('timerId', null);
                    vm.set('data.isSearching', false);
                    refs.nowLocation.setHtml(eachDist);
                }

            } catch(e){
                console.log('Success the getGPS method. But can\'t execute inner process. => '+ e);
            }

        };

        var errorcb = function(pos) {

            //화면이 닫혔을 경우 대비 try~catch
            try{
                clearInterval(vm.get('timerId'));
                vm.set('timerId', null);
                vm.set('data.isSearching', false);
                refs.nowLocation.setHtml('not found position : ' + pos.code + ' - ' + me.getErrMsg(pos.code));
            } catch(e){
                console.log('Fail the getGPS method. And can\'t execute inner process. => '+ e);
            }

            // 로컬일 경우, 테스트 위치 정보
            try{
                // TODO : DELETE // 로컬 Test 전용 좌표
                if(Property.PROFILE === 'L'){

                    var gps = {
                        latitude : 35.1372056,
                        longitude : 128.8577588, // 미음
                        //                 latitude : 35.169393,
                        //                 longitude : 129.176318 // 장산
                    };

                    var latitude = gps.latitude;   //위도
                    var longitude = gps.longitude; //경도

                    var eachDist = 'Local<br>';

                    if(gps && latitude && longitude){
                        var workZoneGps = vm.get('workZoneGps');
                        for(var i in workZoneGps){
                            var location = workZoneGps[i].wkplcNm + '(' + workZoneGps[i].wkplcDvnm + ')';
                            eachDist += me.measureDistance(gps, Number(workZoneGps[i].gpsLatdVal), Number(workZoneGps[i].gpsLotdVal), location);
                            eachDist += '<br>';
                        }
                        refs.nowLocation.setHtml(eachDist);
                    }
                }
                // TODO : DELETE
            } catch(e){
                console.log('Can\'t read local coordinate. => '+ e);
            }

        };

        var opts = {
            enableHighAccuracy : false, //정확성 향상 모드
            timeout : 10 * 1000 //10초
        };

        vm.set('loadingCnt', 10);

        var timerId = setInterval(function(){
            if(vm.get('loadingCnt') > 0){
                vm.set('loadingCnt', vm.get('loadingCnt') - 1);
            }

            refs.nowLocation.setHtml('위치정보 로딩 중...' + vm.get('loadingCnt'));

        }, 1000);

        vm.set('timerId', timerId);

        // Geolocation API - getCurrentPostion : 현재 위치 조회
        navigator.geolocation.getCurrentPosition(successcb, errorcb, opts);

    },

    /* Harversine Formula */
    measureDistance: function(gps, lat, lon, location) {
        Number.prototype.toRad = function() {
            return this * Math.PI / 100;
        };

        var lat1 = Number(gps.latitude);
        var lon1 = Number(gps.longitude);

        var lat2 = Number(lat);
        var lon2 = Number(lon);

        if(!lat1 || !lon1){
            return '위도/경도 거리 변환 실패.';
        }

        var R = 6371; // 지구 반지름 = 6371 km

        var x1 = lat2 - lat1;
        var dLat = x1.toRad();

        var x2 = lon2 - lon1;
        var dLon = x2.toRad();

        var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                Math.cos(lat1.toRad()) * Math.cos(lat2.toRad()) *
                Math.sin(dLon / 2) * Math.sin(dLon / 2);
        var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        var d = R * c;

        var km = String(Math.floor(d)); // '18'
        var strKm = d.toFixed(3); // '18.852'

        var m_tmp = (Number(strKm) - Number(km)) * 1000;
        var m = String(Math.floor(m_tmp));

        var result = '';
        if(km == '0'){
            result = location + ' 근무지와의 거리 : ' + m +'m';
        } else {
            result = location + ' 근무지와의 거리 : ' + km + 'km' + ' ' + m +'m';
        }

        return result;

    },

    /* 현재위치 버튼 탭 이벤트 */
    onBtnGpsAct: function(btnName) {

        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            params = {
                scope : me
            };

        // 이미 위치조회 실행 중일 경우, 중복 실행 차단
        if(vm.get('data.isSearching')){
            return;
        }

        vm.set('data.isSearching', true);

        var successcb = function(pos) {
            var me = params.scope,
                vm = me.getViewModel(),
                refs = me.getReferences(),
                gps = pos.coords;

            var latitude = gps.latitude,   // 위도
                longitude = gps.longitude; // 경도

            if(gps && latitude && longitude) {

                vm.set('gps',gps);

                // 근무지와 현재위치의 거리 계산
                var workZoneGps = vm.get('workZoneGps');
                for(var i in workZoneGps){
                    var location = workZoneGps[i].wkplcNm + '(' + workZoneGps[i].wkplcDvnm + ')';
                    eachDist += me.measureDistance(gps, Number(workZoneGps[i].gpsLatdVal), Number(workZoneGps[i].gpsLotdVal), location);
                    eachDist += '<br>';
                    refs.nowLocation.setHtml(eachDist);
                }

                // 지도에 마크
                Native.addMapMarker('googleMapPanel', '현재위치', gps.latitude, gps.longitude);

            }
            else {
                vm.set('gps', null);
                refs.nowLocation.setHtml('GPS 위도/경도 조회 실패.');
            }

            try{
                vm.set('data.isSearching', false);
            } catch(e){
                console.log(e);
            }
        };

        var errorcb = function(error, params) {
            var me = params.scope,
                vm = me.getViewModel(),
                refs = me.getReferences();

            console.log('code: '    + error.code    + '\n' + 'message: ' + error.message + '\n');

            //화면이 닫혔을 경우 대비 try~catch
            try{
                vm.set('gps', null);
                vm.set('data.isSearching', false);
                refs.nowLocation.setHtml('not found position', error.code + ' - ' + me.getErrMsg(error.code));
            } catch(e){
                console.log(e);
            }

        };

        var opts = {
            enableHighAccuracy : true, //정확성 향상 모드
            timeout : 10 * 1000 //10초
        };

        // Geolocation API - getCurrentPostion : 현재 위치 조회
        navigator.geolocation.getCurrentPosition(successcb, errorcb, opts);
    },

    /* Get the Geolocation API's error message */
    getErrMsg: function(code) {
        var msg = '';

        if(code == '1') {
            msg = "위치 권한 확인 필요";
        }
        else if(code == '2') {
            msg = "위치 정보 조회 실패";
        }
        else if(code == '3') {
            msg = "시간 초과";
        }
        else {
            msg = "원인 확인 필요";
        }

        return msg;
    },

    /* 확인용 버튼 */
    onBtnCurrentPositionCheck: function(button, e, eOpts) {

        var me = this;
        me.getGPS();

    },

    /* 팝업 닫기 */
    onBtnCurrentPositionTapClose: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();

        // runner 내 동작 중인 task 모두 stop
        if(!Ext.isEmpty(vm.get('runnerGps'))){
            vm.get('runnerGps').stopAll();
        }

        me.getView().fireEvent('select', vm.get('gps')); //gps 정보 전달
        me.getView().close();
    },

    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        // 근무지 정보
        var workZoneGps = component.initialConfig.workZoneGps;
        vm.set('workZoneGps', workZoneGps);

        me.getGPS();

    },

    /* 화면 전환 시 기존에 그려진 구글 맵 삭제 */
    onGoogleMapDestroy: function(eOpts) {
        var me = this;
        var refs = me.getReferences();
        var vm = me.getViewModel();

        var runnerGps = vm.get('runnerGps');
        if(!Ext.isEmpty(runnerGps)){
            runnerGps.stopAll();
        }

        Native.removeMap();

    },

    onGoogleMapPainted: function(sender, element, eOpts) {
        var me = this,
            refs = me.getReferences(),
            googleMapPanel = refs.googleMapPanel;

        // 인자1. 패널id
        Native.newInitMap(googleMapPanel.id);

        // geolocation api 지원여부 확인 및 GPS 정보 조회
        try{
            if('geolocation' in navigator){
                // GPS 정보 검색 & 각 근무지별과의 거리 표시
                me.getGPS();
            }
            else{
                refs.nowLocation.setHtml('not support GPS in this browser');
            }
        }
        catch(err){
            console.log(err);
            refs.nowLocation.setHtml(err);
        }
    },

    /* 화면 비활성될 경우, Map객체 제거함 */
    onGoogleMapBeforeHide: function(component, eOpts) {
        var me = this,
            refs = me.getReferences(),
            googleMapPanel = refs.googleMapPanel;

        googleMapPanel.destroy();
    }

});